// KQL reference guide - https://aka.ms/KQLguide
// SQL - KQL conversions - https://aka.ms/sqlcheatsheet
//***********************************************************************************************************

// Use "take" to view a sample number of records in the table and check the data.
YOUR_TABLE_HERE
| take 100

// See how many records are in the table.
YOUR_TABLE_HERE
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)

// Create website visits table
.create table dp700_mv_website_visits (
    visit_id: string,
    visit_timestamp: datetime,
    page: string
)

// Ingest initial website visits with timestamps
.ingest inline into table dp700_mv_website_visits with (format='csv') <|
"v001","2026-09-01T09:15:00Z","Home"
"v002","2026-09-01T11:30:00Z","Contact"
"v003","2026-09-02T14:45:00Z","Home"
"v004","2026-09-03T08:05:00Z","Pricing"
"v005","2026-09-03T20:10:00Z","Blog"

// Query table contents
dp700_mv_website_visits
| order by visit_timestamp asc

// Create materialized view WITHOUT backfill
.create async materialized-view with (
    docString = "Daily website visits without backfill"
) dp700_mv_daily_visits_no_backfill
on table dp700_mv_website_visits
{
    dp700_mv_website_visits
    | extend visit_day = bin(visit_timestamp, 1d)
    | summarize visit_count = count() by visit_day
}

// Query the materialized view without backfill
dp700_mv_daily_visits_no_backfill
| order by visit_day asc

// Create materialized view WITH backfill
.create async materialized-view with (
    backfill = true,
    effectiveDateTime = datetime(2026-06-01T00:00:00Z),
    docString = "Daily website visits with backfill"
) dp700_mv_daily_visits_with_backfill
on table dp700_mv_website_visits
{
    dp700_mv_website_visits
    | extend visit_day = bin(visit_timestamp, 1d)
    | summarize visit_count = count() by visit_day
}

// Query the materialized view with backfill
dp700_mv_daily_visits_with_backfill
| order by visit_day asc

// Show materialized views in the database
.show materialized-views

// Ingest new website visits
.ingest inline into table dp700_mv_website_visits with (format='csv') <|
"v006","2026-09-04T10:10:00Z","Home"
"v007","2026-09-04T12:30:00Z","Contact"

// Query table contents again
dp700_mv_website_visits
| order by visit_timestamp asc

// Query materialized view without backfill after new ingestions
dp700_mv_daily_visits_no_backfill
| order by visit_day asc

// Query materialized view with backfill after new ingestions
dp700_mv_daily_visits_with_backfill
| order by visit_day asc


// Create a simple function to get website visits for a given page
.create-or-alter function get_daily_visits_per_page(pageName:string)
{
    dp700_mv_website_visits
    | where page == pageName
    | extend visit_day = bin(visit_timestamp, 1d)
    | summarize visit_count = count() by visit_day
}

// Query the function to see visits to the 'Home' page
get_daily_visits_per_page("Home")
| order by visit_day asc

// Query the function to see visits to the 'Blog' page
get_daily_visits_per_page("Blog")
| order by visit_day asc


